  </div>
  <div class="err" id="err"></div>
  <p class="hint">Tip: paste a web address and press Save. We'll show its name so you can recognise it later.</p>

  <h2>Saved links (<span id="count">0</span>)</h2>
  <ul id="list"></ul>
  <div class="empty" id="empty">No links saved yet. Paste a link above to get started.</div>
</main>

<script>
  var links = [];
  var nextId = 1;

  // PROTOTYPE ONLY: simulate fetching the page's real <title>.
  // The real app will fetch the actual page title. Here we return a
  // plausible title so the client can experience the flow.
  var knownTitles = {
    'example.com': 'Example Domain',
    'developer.mozilla.org': 'MDN Web Docs',
    'en.wikipedia.org': 'Wikipedia, the free encyclopedia',
    'github.com': 'GitHub',
    'news.ycombinator.com': 'Hacker News'
  };
  function fetchTitle(raw, cb) {
    // Simulate network latency of fetching the page title.
    setTimeout(function () {
      var title;
      try {
        var u = new URL(raw);
        var host = u.hostname.replace(/^www\./, '');
        if (knownTitles[host]) {
          title = knownTitles[host];
        } else {
          var seg = u.pathname.split('/').filter(Boolean).pop();
          if (seg) {
            seg = decodeURIComponent(seg).replace(/[-_]+/g, ' ').replace(/\.[a-z0-9]+$/i, '');
            title = seg.trim().replace(/\b\w/g, function(c){ return c.toUpperCase(); }) +
                    ' — ' + host;
          } else {
            title = host;
          }
        }
      } catch (e) { title = raw; }
      cb(title);
    }, 600);
  }

  function normalise(raw) {
    var v = raw.trim();
    if (!v) return null;
    if (!/^https?:\/\//i.test(v)) v = 'https://' + v;
    try { new URL(v); } catch (e) { return null; }
    return v;
  }

  function render() {
    var list = document.getElementById('list');
    var empty = document.getElementById('empty');
    document.getElementById('count').textContent = links.length;
    list.innerHTML = '';
    if (links.length === 0) { empty.style.display = 'block'; return; }
    empty.style.display = 'none';
    links.forEach(function (item) {
      var host = '';
      try { host = new URL(item.url).hostname.replace(/^www\./, ''); } catch (e) {}
      var li = document.createElement('li');
      li.className = 'card';
      if (item.editing) {
        li.innerHTML =
          '<div class="titlerow">' +
            '<input class="titleedit" type="text" />' +
            '<button class="editbtn savename">Save name</button>' +
          '</div>' +
          '<a href="' + item.url + '" target="_blank" rel="noopener"></a>' +
          '<div class="meta">' + host + ' · saved just now</div>';
        var field = li.querySelector('.titleedit');
        field.value = item.title;
        li.querySelector('.savename').addEventListener('click', function () {
          var v = field.value.trim();
          if (v) item.title = v;
          item.editing = false; render();
        });
        field.addEventListener('keydown', function (e) {
          if (e.key === 'Enter') { var v = field.value.trim(); if (v) item.title = v; item.editing = false; render(); }
        });
      } else {
        li.innerHTML =
          '<div class="titlerow">' +
            '<div class="title' + (item.fetching ? ' fetching' : '') + '"></div>' +
            (item.fetching ? '' : '<button class="editbtn">Rename</button>') +
          '</div>' +
          '<a href="' + item.url + '" target="_blank" rel="noopener"></a>' +
          '<div class="meta">' + host + ' · saved just now</div>';
        li.querySelector('.title').textContent = item.fetching ? 'Fetching page title…' : item.title;
        li.querySelector('a').textContent = item.url;
        var eb = li.querySelector('.editbtn');
        if (eb) eb.addEventListener('click', function () { item.editing = true; render();
          var f = document.querySelector('.titleedit'); if (f) { f.focus(); f.select(); } });
      }
      list.appendChild(li);
    });
  }

  function save() {
    var input = document.getElementById('url');
    var err = document.getElementById('err');
    var url = normalise(input.value);
    if (!url) {
      err.textContent = 'That doesn\'t look like a valid link. Try something like example.com/page.';
      err.style.display = 'block';
      return;
    }
    err.style.display = 'none';
    var item = { id: nextId++, url: url, title: '', fetching: true, editing: false };
    links.unshift(item);
    input.value = '';
    input.focus();
    render();
    fetchTitle(url, function (title) {
      item.title = title;
      item.fetching = false;
      render();
    });
  }

  document.getElementById('saveBtn').addEventListener('click', save);
  document.getElementById('url').addEventListener('keydown', function (e) {
    if (e.key === 'Enter') save();
  });

  render();
  document.body.setAttribute('data-harness-ready', 'true');
</script>
